(async()=>{
  const E=__echoes;
  const sleep=(ms)=>new Promise(r=>setTimeout(r,ms));
  const raf=()=>new Promise(r=>requestAnimationFrame(r));
  const o={};
  E.cmd('giveSkill','warding_aura');
  E.cmd('grantNode','echo');
  o.sock=E.cmd('socket','warding_aura','echo',0);
  // park allies inside the 0.9 u field and keep them hurt
  E.cmd('placeAlly',1,0.4,0.2); E.cmd('placeAlly',2,-0.4,0.2); E.cmd('placeAlly',3,0,-0.45);
  E.cmd('setHp',1,0.2); E.cmd('setHp',2,0.2); E.cmd('setHp',3,0.2);
  await raf();
  const t0=E.tick;
  // keep them topped-down so heals always apply
  const iv=setInterval(()=>{E.cmd('setHp',1,0.2);E.cmd('setHp',2,0.2);E.cmd('setHp',3,0.2);},200);
  await sleep(7000);
  clearInterval(iv);
  const ev=E.events.filter(e=>e.tick>=t0&&e.type==='aura_pulse');
  o.pulses=ev.map(e=>({tick:e.tick,echo:!!e.echo,healed:e.healed}));
  const echoTicks=o.pulses.filter(p=>p.echo).map(p=>p.tick);
  o.echoTicks=echoTicks;
  o.echoDeltas=echoTicks.slice(1).map((t,i)=>t-echoTicks[i]);
  const normTicks=o.pulses.filter(p=>!p.echo).map(p=>p.tick);
  o.normDeltas=normTicks.slice(1).map((t,i)=>t-normTicks[i]);
  const heals=E.events.filter(e=>e.tick>=t0&&e.type==='heal'&&e.source==='warding_aura');
  o.healAmounts=[...new Set(heals.map(h=>h.amount))];
  o.bounceHops=E.events.filter(e=>e.type==='bounce_hop').length;
  o.pos=E.state().party.map(p=>({c:p.classId||p.kind,x:p.x,z:p.z}));
  return JSON.stringify(o);
})()
